// 4. GLOBOPLAY
export const GloboplayLogo: React.FC<LogoProps> = ({ className = 'h-5 w-auto' }) => (
  <svg viewBox="0 0 110 28" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-label="Globoplay">
    <defs>
      <linearGradient id="gpGrad" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#FB3E44" />
        <stop offset="50%" stopColor="#FF7700" />
        <stop offset="100%" stopColor="#FFB300" />
      </linearGradient>
    </defs>
    {/* Globo text */}
    <text x="0" y="20" fill="currentColor" fontFamily="sans-serif" fontWeight="700" fontSize="19" letterSpacing="-0.5px">
      globo
    </text>
    {/* Play text in gradient */}
    <text x="56" y="20" fill="url(#gpGrad)" fontFamily="sans-serif" fontWeight="800" fontSize="19" letterSpacing="-0.5px">
      play
    </text>
  </svg>
);

// 5. REDE GLOBO
export const RedeGloboLogo: React.FC<LogoProps> = ({ className = 'h-6 w-auto' }) => (
  <svg viewBox="0 0 32 32" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-label="Rede Globo">
    <defs>
      <linearGradient id="globoSphere" x1="20%" y1="15%" x2="85%" y2="85%">
        <stop offset="0%" stopColor="#FFFFFF" />
        <stop offset="35%" stopColor="#D5D9E0" />
        <stop offset="70%" stopColor="#8A92A0" />
        <stop offset="100%" stopColor="#4A5260" />
      </linearGradient>
      <linearGradient id="globoScreen" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#00A3E0" />
        <stop offset="30%" stopColor="#00C48C" />
        <stop offset="60%" stopColor="#FFDD00" />
        <stop offset="100%" stopColor="#FF3333" />
      </linearGradient>
    </defs>
    {/* Outer Silver Sphere */}
    <circle cx="16" cy="16" r="14.5" fill="url(#globoSphere)" />
    {/* Screen Aperture cut out */}
    <rect x="7.5" y="9" width="17" height="14" rx="4" fill="url(#globoScreen)" stroke="#FFFFFF" strokeWidth="0.8" />
    {/* Inner Sphere pupil */}
    <circle cx="16" cy="16" r="4.8" fill="url(#globoSphere)" />
  </svg>
);

