export const ClientLogoRenderer: React.FC<{ logoKey: string; className?: string }> = ({ logoKey, className }) => {
  switch (logoKey) {
    case 'netflix':
      return <NetflixLogo className={className} />;
    case 'hbo':
      return <HboLogo className={className} />;
    case 'prime':
      return <PrimeVideoLogo className={className} />;
    case 'globoplay':
      return <GloboplayLogo className={className} />;
    case 'globo':
      return <RedeGloboLogo className={className} />;
    case 'gloob':
      return <GloobLogo className={className} />;
    case 'cocacola':
      return <CocaColaLogo className={className} />;
    case 'loreal':
      return <LorealLogo className={className} />;
    case 'samsung':
      return <SamsungLogo className={className} />;
    case 'aiwa':
      return <AiwaLogo className={className} />;
    case 'mondial':
      return <MondialLogo className={className} />;
    default:
      return null;
  }
};

export const ToolLogoRenderer: React.FC<{ toolKey: string; className?: string }> = ({ toolKey, className }) => {
  switch (toolKey) {
    case 'avid':
      return <AvidLogo className={className} />;
    case 'premiere':
      return <PremiereLogo className={className} />;
    case 'davinci':
      return <DaVinciLogo className={className} />;
    case 'capcut':
      return <CapCutLogo className={className} />;
    case 'photoshop':
      return <PhotoshopLogo className={className} />;
    case 'ai':
      return <AiWorkflowLogo className={className} />;
    default:
      return null;
  }
};
